#!/usr/bin/env python3
"""WIN-010 / EXP-684-rev2 hole-1 check: what does BOU Z do on 2017-08-21 relative to
(a) the dome's OPEN-009 baseline (2017-08-20 daily mean) and (b) same-UT quiet-day references?
Inputs: USGS geomag web service IAGA-2002 minute files day_2017-08-DD.txt (BOU, variation/best-available),
        GFZ definitive Kp JSON kp.json (2017-08-10..31).
Data: INTERMAGNET definitive via BGS GIN (publicationState=definitive). Eclipse at BOU (DE421 / timeanddate): 16:23-19:14 UT, max 17:46-17:47 UT. Dome minimum claim: 17:20 UT."""
import json, glob, statistics as st, hashlib, sys, os
D = os.path.dirname(os.path.abspath(__file__))
def load(day):
    f = os.path.join(D, f'day_2017-08-{day:02d}.txt'); rows = {}
    hdr = None
    for ln in open(f):
        if ln.startswith('DATE'): hdr = ln.split(); continue
        if hdr and ln[:4].isdigit():
            p = ln.split(); t = p[1][:5]; vals = dict(zip(hdr[3:], map(float, p[3:])))
            rows[t] = vals
    return rows, hdr
def key(h, comp): return [k for k in h[3:] if k.endswith(comp)][0]
d21, h = load(21); ZK, XK = key(h,'Z'), key(h,'X')
def good(v): return v < 88888
def series(rows, k): return {t: v[k] for t, v in rows.items() if good(v[k])}
def tmin(t): return int(t[:2])*60+int(t[3:5])
def win(s, a, b): return {t: v for t, v in s.items() if a <= tmin(t) <= b}
E0, E1, EMAX = tmin('16:23'), tmin('19:14'), tmin('17:46')
out = {}
# (1) dome OPEN-009 replication: Aug20 daily mean vs Aug21 eclipse-window min
z20 = series(load(20)[0], ZK); z21 = series(d21, ZK)
m20 = st.mean(z20.values()); w21 = win(z21, E0, E1); tm = min(w21, key=w21.get)
out['dome_open009_replication'] = {'aug20_daily_mean_Z': round(m20,2), 'aug21_eclipse_window_min_Z': round(w21[tm],2),
  'min_time_ut': tm, 'difference_nT': round(w21[tm]-m20,2), 'dome_published': {'aug20_mean':47731.12,'eclipse_min':47712.90,'diff':-18.22}}
# (2) same statistic on a non-eclipse day: Aug20 itself (min in 16:23-19:14 UT vs Aug19 daily mean) and each quiet day vs own daily mean
kp = json.load(open(os.path.join(D,'kp.json')))
daykp = {}
for t, v in zip(kp['datetime'], kp['Kp']): daykp.setdefault(int(t[8:10]), []).append(v)
cands = [d for d in range(10,32) if d != 21 and len(daykp.get(d,[]))==8]
quiet = sorted(cands, key=lambda d: (max(daykp[d]), sum(daykp[d])))[:5]
out['quiet_days_selected'] = {'rule':'5 days in 2017-08-10..31 (excl. 21) with lowest daily max Kp, ties by daily Kp sum', 'days':[f'2017-08-{d:02d}' for d in sorted(quiet)], 'max_kp':{f'2017-08-{d:02d}':max(daykp[d]) for d in sorted(quiet)}}
same_stat = {}
for d in sorted(quiet):
    zd = series(load(d)[0], ZK); wd = win(zd, E0, E1); tt = min(wd, key=wd.get)
    same_stat[f'2017-08-{d:02d}'] = {'window_min_minus_daily_mean_nT': round(wd[tt]-st.mean(zd.values()),2), 'min_time_ut': tt}
out['same_statistic_on_quiet_days'] = same_stat
# (3) quiet-day-referenced dZ, dX on eclipse day (mean of 5 quiet days at same UT)
ref = {}
for comp,K in (('Z',ZK),('X',XK)):
    qs = [series(load(d)[0], K) for d in quiet]; s21 = series(d21, K)
    dd = {t: s21[t]-st.mean(q[t] for q in qs) for t in s21 if all(t in q for q in qs)}
    # remove offset using pre-eclipse hour 15:20-16:20 UT
    pre = st.mean(v for t,v in dd.items() if tmin('15:20')<=tmin(t)<=tmin('16:20'))
    d2 = {t: v-pre for t,v in dd.items()}
    w = win(d2, E0, E1)
    ref[comp] = {'at_17:20': round(d2['17:20'],2), 'at_17:46': round(d2['17:46'],2),
                 'window_min': round(min(w.values()),2), 'window_min_time': min(w,key=w.get),
                 'window_max': round(max(w.values()),2), 'window_max_time': max(w,key=w.get)}
    # Meza-style: 2h window centred on max, linear detrend of eclipse-minus-reference
    w2 = win(dd, EMAX-60, EMAX+60); ts = sorted(w2, key=tmin); xs=[tmin(t) for t in ts]; ys=[w2[t] for t in ts]
    n=len(xs); mx=sum(xs)/n; my=sum(ys)/n; b=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/sum((x-mx)**2 for x in xs)
    r = {t: y-(my+b*(x-mx)) for t,x,y in zip(ts,xs,ys)}
    ref[comp]['meza_style_2h_detrended'] = {'at_17:20': round(r['17:20'],2), 'at_17:46': round(r['17:46'],2), 'min': round(min(r.values()),2), 'min_time': min(r,key=r.get), 'max': round(max(r.values()),2), 'max_time': max(r,key=r.get)}
out['eclipse_day_minus_quiet_mean'] = ref
out['inputs_sha256'] = {os.path.basename(f): hashlib.sha256(open(f,'rb').read()).hexdigest() for f in sorted(glob.glob(os.path.join(D,'day_*.txt')))+[os.path.join(D,'kp.json')]}
out['data_header_type'] = [l.strip() for l in open(os.path.join(D,'day_2017-08-21.txt')) if 'Data Type' in l or 'Data Interval' in l][:2]
print(json.dumps(out, indent=1))
